const notice=document.querySelector('#notice');let timer;
document.querySelectorAll('[data-notice]').forEach(b=>b.addEventListener('click',()=>{notice.textContent=b.dataset.notice;notice.hidden=false;clearTimeout(timer);timer=setTimeout(()=>notice.hidden=true,6000)}));
const menu=document.querySelector('.menu'),mobileNav=document.querySelector('#mobile-nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));mobileNav.hidden=!open});mobileNav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{mobileNav.hidden=true;menu.setAttribute('aria-expanded','false')}));
let active=-1;function select(i){if(i===active)return;active=i;document.querySelectorAll('.point').forEach(p=>p.classList.toggle('active',Number(p.dataset.point)===i));document.querySelectorAll('.map-label').forEach(l=>{const name=document.querySelector('.point[data-point="'+i+'"] title')?.textContent;if(name)l.textContent=name})}select(Number(document.querySelector('[data-property-index]')?.dataset.propertyIndex || 0));
const stories=[...document.querySelectorAll('[data-story]')];let queued=false;function follow(){queued=false;const anchor=innerWidth<=760?330:innerHeight*.43;let chosen=0;stories.forEach((s,i)=>{if(s.getBoundingClientRect().top<=anchor)chosen=i});select(chosen)}if(stories.length){addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(follow)}},{passive:true});addEventListener('resize',follow);follow()}
const dialog=document.querySelector('#map-dialog');document.querySelectorAll('.expand-map').forEach(b=>b.addEventListener('click',()=>{const container=b.closest('.map-sticky')||b.parentElement;dialog.querySelector('.large-map').innerHTML=container.querySelector('.map').outerHTML;dialog.showModal()}));dialog.querySelector('.close-map').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
